def centralizar(valores):
    if not valores:
        raise ValueError("Preciso de pelo menos um valor")
    media = sum(valores) / len(valores)
    return [x - media for x in valores]
entrada = [2, 4, 6]
assert centralizar(entrada) == [-2, 0, 2]
assert entrada == [2, 4, 6]
try:
    centralizar([])
except ValueError:
    pass
else:
    raise AssertionError("Lista vazia precisa ser rejeitada")
